import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me, last_opp = history[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c

    if opp_d == 0:
        if n >= 90:
            return 'D' if rng.random() < 0.35 else 'C'
        if n >= 70 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if opp_c == 0:
        if rng.random() < 0.04 and n > 20:
            return 'C'
        return 'D'

    window = 12 if n >= 12 else n
    recent_opp = opp[-window:]
    r_opp_c = recent_opp.count('C')
    r_opp_d = window - r_opp_c

    last5_opp_d = opp[-5:].count('D') if n >= 5 else opp_d
    last5_opp_c = len(opp[-5:]) - opp[-5:].count('D') if n >= 5 else opp_c

    if n >= 8 and r_opp_c >= window - 1:
        if n >= 85:
            return 'D' if rng.random() < 0.5 else 'C'
        if n >= 45 and rng.random() < 0.10:
            return 'D'
        return 'C'

    if n >= 8 and r_opp_d >= window - 1:
        if n >= 95:
            return 'D'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if n >= 90:
            if opp_c * 5 >= n * 4:
                return 'D'
            return 'C'
        if n >= 60 and opp_c * 5 >= n * 4 and rng.random() < 0.12:
            return 'D'
        if last_me == 'D' and last5_opp_c >= 3:
            return 'C'
        if n >= 6 and last5_opp_d >= 3:
            return 'D'
        return 'C'

    opp_recent_ratio_c = r_opp_c / float(window)
    opp_recent_ratio_d = r_opp_d / float(window)

    if r_opp_d >= 2 and opp_recent_ratio_d > 0.6:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if r_opp_d == 1 and opp_recent_ratio_c >= 0.75:
        if last_me == 'D':
            return 'C'
        return 'D' if n >= 4 and opp[-4:].count('D') >= 2 else 'C'

    if n >= 6:
        if opp_recent_ratio_c >= 0.6:
            return 'C'
        if opp_recent_ratio_c <= 0.35:
            return 'D'

    if last_me == 'D':
        if rng.random() < 0.30:
            return 'C'
        return 'D'

    return 'D'
